size_t fn_14(const unsigned char *in, size_t inlen,
                    const char *const argv[], char *out, size_t outlen)
{
    size_t i, j;
    unsigned int c;
    static const char *const tbl =
        "AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B";

    if (outlen < (inlen + 2) / 3 * 4)
        return (size_t)-1;

    for (i = j = 0; i < inlen; i += 3, j += 4) {
        c = (in[i] << 16) | (in[i + 1] << 8) | in[i + 2];
        out[j] = tbl[(c >> 18) & 0x3f];
        out[j + 1] = tbl[(c >> 12) & 0x3f];
        out[j + 2] = tbl[(c >> 6) & 0x3f];
        out[j + 3] = tbl[c & 0x3f];
    }

    switch (inlen - i) {
    case 0:
        break;
    case 1:
        c = in[i] << 16;
        out[j] = tbl[(c >> 18) & 0x3f];
        out[j + 1] = tbl[(c >> 12) & 0x3f];
        out[j + 2] = '=';
        out[j + 3] = '=';
        j += 4;
        break;
    case 2:
        c = (in[i] << 16) | (in[i + 1] << 8);
        out[j] = tbl[(c >> 18) & 0x3f];
        out[j + 1] = tbl[(c >> 12) & 0x3f];
        out[j + 2] = tbl[(c >> 6) & 0x3f];
        out[j + 3] = '=';
        j += 4;
        break;
    }

    return j;
}
